# ! [doc = " IEEE 754-2019 `minimum`."] # ! [doc = ""] # ! [doc = " Per the spec, returns the canonicalized result of:"] # ! [doc = " - `x` if `x < y`"] # ! [doc = " - `y` if `y < x`"] # ! [doc = " - -0.0 if x and y are zero with opposite signs"] # ! [doc = " - qNaN if either operation is NaN"] # ! [doc = ""] # ! [doc = " Excluded from our implementation is sNaN handling."] use split_decls_genesis :: ourprelude :: * ; use crate :: support :: Float ; #[inline] pub fn fminimum < F : Float > (x : F , y : F) -> F { let res = if x . is_nan () { x } else if y . is_nan () { y } else if x < y || (x . biteq (F :: NEG_ZERO) && y . is_sign_positive ()) { x } else { y } ; res . canonicalize () }